// n8n Code node: Run Once for All Items, after Needs OCR?1 (true branch).
// ponytail: Vision files:annotate (sync) reads at most 5 pages per request, so one request per 5-page chunk. Switch to asyncBatchAnnotate + GCS if PDFs exceed the 20 MB request cap.
const item = $input.first();
const key = Object.keys(item.binary ?? {})[0];
let buffer;
if (key) {
  buffer = await this.helpers.getBinaryDataBuffer(0, key);
} else {
  // Read PDF1 dropped the binary (Keep Source != Both); fall back to the downloaded file when it is still in memory.
  const source = $('Download File').first().binary?.data;
  if (!source?.data || source.id) throw new Error('PDF binary missing. Set Read PDF1 > Options > Keep Source to "Both".');
  buffer = Buffer.from(source.data, 'base64');
}
const content = buffer.toString('base64');
const pages = Math.max(Number(item.json.numpages) || 1, 1);
const output = [];
for (let first = 1; first <= pages; first += 5) {
  const chunk = Array.from({ length: Math.min(5, pages - first + 1) }, (_, i) => first + i);
  output.push({
    json: { pages: chunk, body: { requests: [{ inputConfig: { mimeType: 'application/pdf', content }, features: [{ type: 'DOCUMENT_TEXT_DETECTION' }], pages: chunk }] } },
    pairedItem: { item: 0 },
  });
}
return output;

// Reject partial OCR: one failed/missing page makes this attachment incomplete.
const items = $input.all();
const pages = [];
for (const item of items) {
  if (item.json.error) throw new Error('Google Vision OCR failed: ' + String(item.json.error.message ?? item.json.error));
  const files = item.json.responses;
  if (!Array.isArray(files) || files.length !== 1) throw new Error('Google Vision OCR returned no file result.');
  for (const file of files) {
    if (file.error) throw new Error('Google Vision OCR failed: ' + String(file.error.message ?? file.error));
    if (!Array.isArray(file.responses) || !file.responses.length) throw new Error('Google Vision OCR returned no pages.');
    for (const page of file.responses) {
      if (page.error) throw new Error('Google Vision OCR page failed: ' + String(page.error.message ?? page.error));
      pages.push(page);
    }
  }
}
const expectedPages = $('Build Vision Request1').all().flatMap(item => item.json.pages);
const returnedPages = pages.map(page => page.context?.pageNumber);
if (pages.length !== expectedPages.length || new Set(returnedPages).size !== expectedPages.length ||
    expectedPages.some(page => !returnedPages.includes(page))) {
  throw new Error('Google Vision OCR returned incomplete PDF pages; manual review required.');
}
const text = pages.map(page => page.fullTextAnnotation?.text ?? '').join('\n').trim();
if (!text) throw new Error('Google Vision OCR found no readable text in the PDF.');
return [{ json: { text, ocr: 'google-vision' }, pairedItem: { item: 0 } }];

const metadata = $('Validate Attachment Match').item.json;
  const text = $json.document_text ?? $json.text ?? $json.data;
  if (typeof text !== 'string' || !text.trim()) throw new Error('No readable document text. Image-only PDFs/DOCX need OCR.');
  // Reject empty/binary-looking decoded text before sending it to the LLM.
  if (!/[\p{L}\p{N}]/u.test(text) || /[\u0000-\u0008\u000B\u000C\u000E-\u001F\uFFFD]/u.test(text)) {
    throw new Error('Attachment contains unreadable or corrupted text; provide a readable copy.');
  }
  // ponytail: reject oversized documents instead of silently truncating shipment fields; add chunking when needed.
  if (text.length > 60000) throw new Error('Document exceeds the 60,000-character extraction limit; split it before retrying.');
  const hint = metadata.filename.match(/(?:^|[^a-z0-9])(BL|SI)(?=[^a-z0-9]|$)/i)?.[1]?.toUpperCase() ?? 'UNKNOWN';
  return { json: { ...metadata, document_type_hint: hint, document_text: text.trim() } };

const metadata = $('Normalize & Tag Data').item.json;
  let extracted = $json.text ?? $json.output ?? $json;
  if (typeof extracted === 'string') {
    try { extracted = JSON.parse(extracted.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')); }
    catch { throw new Error('Field Normalise returned invalid JSON.'); }
  }
  if (!extracted || typeof extracted !== 'object' || Array.isArray(extracted)) throw new Error('Field Normalise must return an object.');
  const { document_type, ...extracted_fields } = extracted;
  if (!['BL', 'SI'].includes(document_type)) throw new Error('Document is not identifiable as BL or SI; manual review required.');
  if (metadata.document_type_hint !== 'UNKNOWN' && metadata.document_type_hint !== document_type) throw new Error('Document type disagrees with the BL/SI filename; manual review required.');
  return { json: { email_id: metadata.email_id, filename: metadata.filename, source_file_id: metadata.source_file_id, document_type, extracted_fields } };

